__NUXT_JSONP__("/ch/about", (function(a){return {data:[{details:{slug:"ch",pageTitle:"MLI概况 | Mentor Language Institute",pageDescription:"Mentor Language Institute语言学院成立于2002年",section1:{title:"MLI概况",description:["Mentor Language Institute语言学院成立于2002年。\u003Cbr \u002F\u003E地点：Westwood & Hollywood"]},section2:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fpay-less-for-quality-classes.jpg",title:"花更少的钱 学高品质的课",description:["我们重视两件事情： \u003Cb\u003E教育品质\u003C\u002Fb\u003E 与 \u003Cb\u003E价格\u003Cb\u003E","英语是全球性的语言，是一个和来自世界各地的人沟通的必要工具。我们希望国际学生拥有英语能力，在世界上获得成功。因此，我们着重于课程品质及低价位的课程。"]},section3:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fmli-staff.jpg",title:"截至2020年，超过17000位学生选择MLI并毕业于此",description:["我们有ESL课程（一般英语课程包和六大项目：文法\u002F写作，阅读\u002F单字及听力\u002F口说），TOEFL®，IELTS™（预准备念大专院校的学生），和 TOEIC®。"],lists:[{link:"\u002Fch\u002Ffeature",image:a,text:" 选择MLI的五个理由"},{link:"\u002Fch\u002Fcompany",image:a,text:" 学校信息"},{link:"\u002Fch\u002Fimage-gallery",image:a,text:" 照片\u002F影片总览"}]},dir:"\u002Fabout",path:"\u002Fabout\u002Fch",extension:".json",createdAt:"2026-10-22T16:31:28.432Z",updatedAt:"2025-05-26T12:06:27.571Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg")));